<?php

$lesson = function (string $title, string $summary, string $code, string $task, string $correct): array {
    return [
        'title' => $title,
        'summary' => $summary,
        'code' => $code,
        'task' => $task,
        'options' => [
            $correct,
            'It is only a frontend feature and does not run inside the Spring container.',
            'It always requires XML configuration and an external application server.',
            'It disables dependency injection and database transactions.',
        ],
        'answer' => 0,
        'why' => $correct,
    ];
};

return [
    $lesson('What is Spring Framework?', 'Spring Framework provides the infrastructure for enterprise Java applications: IoC, dependency injection, AOP, transactions, MVC, REST, security and data access.', "@Configuration\n@ComponentScan(\"com.ascendia\")\nclass ApplicationConfig {}", 'Create a configuration class and register one service as a Spring bean.', 'Spring is an enterprise Java framework centered on IoC and dependency injection.'),
    $lesson('What is Spring Boot?', 'Spring Boot builds on Spring and reduces setup through auto-configuration, starter dependencies, embedded servers and production-ready conventions.', "@SpringBootApplication\npublic class Application {\n  public static void main(String[] args) {\n    SpringApplication.run(Application.class, args);\n  }\n}", 'Generate a project with Spring Initializr and start it from the main method.', 'Spring Boot simplifies Spring applications with conventions, auto-configuration and embedded runtime support.'),
    $lesson('Spring versus Spring Boot', 'Spring supplies the core framework; Spring Boot supplies opinionated defaults, dependency starters, an embedded server and faster application bootstrap.', "// Spring Boot starter\nimplementation(\"org.springframework.boot:spring-boot-starter-web\")", 'List which setup steps Boot removes from a traditional Spring MVC deployment.', 'Spring Boot extends Spring and minimizes manual configuration; it does not replace the Spring container.'),
    $lesson('What does @SpringBootApplication do?', '@SpringBootApplication combines configuration, auto-configuration and component scanning for the application package hierarchy.', "@SpringBootApplication // @Configuration + @EnableAutoConfiguration + @ComponentScan\npublic class JobsApi {}", 'Move the main class to a parent package and verify that controllers are discovered.', 'It combines @Configuration, @EnableAutoConfiguration and @ComponentScan.'),
    $lesson('What is auto-configuration?', 'Boot inspects classpath dependencies, properties and existing beans, then conditionally creates sensible infrastructure beans.', "@Bean\n@ConditionalOnMissingBean\nClock applicationClock() { return Clock.systemUTC(); }", 'Add JDBC and inspect the auto-configuration report to see DataSource conditions.', 'Auto-configuration conditionally supplies beans based on the classpath, properties and beans already defined.'),
    $lesson('What are Spring Boot starters?', 'Starters are curated dependency bundles for capabilities such as web, JPA, security and testing, with compatible transitive versions managed by Boot.', "implementation(\"org.springframework.boot:spring-boot-starter-web\")\ntestImplementation(\"org.springframework.boot:spring-boot-starter-test\")", 'Replace individual MVC dependencies with the web starter and inspect the dependency tree.', 'A starter is a managed dependency bundle for a specific application capability.'),
    $lesson('What is an embedded server?', 'A Boot web application can package Tomcat, Jetty or Undertow and run as an executable JAR without deploying a WAR to a separate server.', "./mvnw clean package\njava -jar target/jobs-api.jar", 'Build an executable JAR and run it on port 8081.', 'The HTTP server is packaged with the application and starts with the executable JAR.'),
    $lesson('What is Inversion of Control?', 'IoC means the Spring container creates, configures and connects application objects instead of business code manually constructing its dependency graph.', "@Service\nclass JobService {\n  private final JobRepository jobs;\n  JobService(JobRepository jobs) { this.jobs = jobs; }\n}", 'Remove a manual new JobRepository() call and let the container supply it.', 'IoC transfers object creation and lifecycle control to the Spring container.'),
    $lesson('What is Dependency Injection?', 'Dependency injection supplies collaborators to a class. Constructor injection makes required dependencies explicit, testable and immutable.', "@RestController\nclass JobController {\n  private final JobService service;\n  JobController(JobService service) { this.service = service; }\n}", 'Unit-test the controller by passing a mocked JobService to its constructor.', 'Constructor injection explicitly supplies required collaborators and is generally preferred.'),
    $lesson('What is a Spring Bean?', 'A bean is an object created and managed by an ApplicationContext, including its dependencies, scope and lifecycle callbacks.', "@Component\nclass SalaryCalculator {\n  BigDecimal annual(BigDecimal monthly) { return monthly.multiply(BigDecimal.valueOf(12)); }\n}", 'Retrieve the bean from an application-context test and invoke it.', 'A Spring bean is an object whose creation and lifecycle are managed by the IoC container.'),

    $lesson('@Component, @Service and @Repository', 'All three register beans. @Component is generic, @Service communicates business logic, and @Repository marks persistence code and supports persistence exception translation.', "@Repository interface JobRepository extends JpaRepository<Job, Long> {}\n@Service class JobService {}", 'Annotate each layer of a small job-search use case appropriately.', 'They are stereotype annotations; @Service and @Repository express layer-specific intent.'),
    $lesson('What is @Controller?', '@Controller is used in Spring MVC when handler methods resolve views or templates, although a method can use @ResponseBody for serialized output.', "@Controller\nclass HomeController {\n @GetMapping(\"/\") String home() { return \"home\"; }\n}", 'Return a Thymeleaf view from a controller and pass one model attribute.', '@Controller normally participates in MVC view rendering.'),
    $lesson('What is @RestController?', '@RestController combines @Controller and @ResponseBody so handler return values are serialized as JSON or another negotiated representation.', "@RestController\n@RequestMapping(\"/api/jobs\")\nclass JobController {\n @GetMapping List<JobDto> index() { return List.of(); }\n}", 'Create a GET endpoint and confirm the response Content-Type is application/json.', '@RestController serializes handler return values into the HTTP response body.'),
    $lesson('What is @RequestMapping?', '@RequestMapping defines URI, HTTP method, headers, consumes and produces conditions at class or method level.', "@RestController\n@RequestMapping(value=\"/api/v1/jobs\", produces=MediaType.APPLICATION_JSON_VALUE)\nclass JobController {}", 'Add a shared /api/v1/jobs prefix to two handler methods.', '@RequestMapping establishes reusable request-matching conditions.'),
    $lesson('@GetMapping versus @PostMapping', '@GetMapping reads resources and should be safe; @PostMapping creates or triggers processing and normally receives a request body.', "@GetMapping List<JobDto> all() { return service.all(); }\n@PostMapping ResponseEntity<JobDto> create(@Valid @RequestBody CreateJobRequest body) { return ResponseEntity.status(201).body(service.create(body)); }", 'Implement GET and POST for a jobs collection with correct status codes.', '@GetMapping handles GET requests while @PostMapping handles POST requests.'),
    $lesson('What is @PathVariable?', '@PathVariable binds a URI-template segment such as /jobs/{id} to a method parameter.', "@GetMapping(\"/{id}\")\nJobDto show(@PathVariable long id) { return service.find(id); }", 'Add an endpoint for /api/jobs/42 and validate a missing job returns 404.', '@PathVariable reads a value embedded in the request path.'),
    $lesson('What is @RequestParam?', '@RequestParam binds query-string or form parameters and can declare default values and optional parameters.', "@GetMapping\nPage<JobDto> search(@RequestParam String skill, @RequestParam(defaultValue=\"0\") int page) { return service.search(skill, page); }", 'Support /api/jobs?skill=java&page=0.', '@RequestParam reads named request parameters such as query-string values.'),
    $lesson('What is @RequestBody?', '@RequestBody asks an HttpMessageConverter, usually Jackson, to deserialize the request payload into a Java object.', "record CreateJobRequest(@NotBlank String title, @NotBlank String location) {}\n@PostMapping void create(@Valid @RequestBody CreateJobRequest request) {}", 'Submit valid and malformed JSON and compare the responses.', '@RequestBody deserializes the HTTP body into a Java value.'),
    $lesson('What is @ResponseBody?', '@ResponseBody writes a controller method return value to the HTTP response using message converters rather than resolving it as a view name.', "@Controller\nclass HealthController {\n @ResponseBody @GetMapping(\"/health-text\") Map<String,String> health() { return Map.of(\"status\",\"UP\"); }\n}", 'Return a small JSON health response from a regular @Controller.', '@ResponseBody serializes a return value instead of treating it as a view.'),
    $lesson('What is @Qualifier?', '@Qualifier selects a specific bean when multiple candidates implement the same interface. Constructor parameters can carry the qualifier.', "interface PaymentGateway {}\n@Component(\"stripe\") class StripeGateway implements PaymentGateway {}\nclass BillingService { BillingService(@Qualifier(\"stripe\") PaymentGateway gateway) {} }", 'Create two gateway beans and inject the desired implementation explicitly.', '@Qualifier disambiguates multiple beans of the same dependency type.'),

    $lesson('What are bean scopes?', 'Scope controls bean lifetime and visibility. Common scopes are singleton, prototype, request, session and application.', "@RequestScope\n@Component\nclass RequestAuditContext {}", 'Compare object identities for singleton and prototype beans.', 'Bean scope defines how many instances exist and how long they live.'),
    $lesson('What is a singleton bean?', 'Singleton is the default Spring scope: one bean instance per ApplicationContext, so mutable state must be handled safely.', "@Service\nclass JobSearchService { /* keep request-specific state out */ }", 'Send concurrent requests and ensure the singleton service holds no per-user fields.', 'A singleton scope creates one instance per Spring application context.'),
    $lesson('What is a prototype bean?', 'A prototype bean is created each time the container resolves it; Spring does not manage the complete destruction lifecycle after creation.', "@Scope(ConfigurableBeanFactory.SCOPE_PROTOTYPE)\n@Component\nclass ImportWorkspace {}", 'Request two prototype instances and assert they are different objects.', 'Prototype scope returns a new bean instance for each container lookup or injection resolution.'),
    $lesson('What is @Primary?', '@Primary marks the default candidate when multiple beans match a single injection point; @Qualifier can still override it.', "@Primary\n@Component\nclass DefaultTaxCalculator implements TaxCalculator {}", 'Register default and international calculators and inject each intentionally.', '@Primary identifies the default bean among multiple candidates of one type.'),
    $lesson('What is @Configuration?', '@Configuration declares a class containing bean definitions. Its @Bean methods are managed to preserve container semantics.', "@Configuration\nclass ClientConfig {\n @Bean Clock clock() { return Clock.systemUTC(); }\n}", 'Create a Clock bean and inject it into a service instead of calling now() directly.', '@Configuration is a source of Spring-managed bean definitions.'),
    $lesson('What is @Bean?', '@Bean registers the object returned by a configuration method, useful for third-party classes that cannot be annotated.', "@Bean\nObjectMapper objectMapper() {\n return JsonMapper.builder().findAndAddModules().build();\n}", 'Configure and inject a third-party client using a @Bean method.', '@Bean explicitly registers a method return value in the Spring container.'),
    $lesson('What is component scanning?', 'Component scanning discovers stereotype-annotated classes under configured packages and registers bean definitions.', "@ComponentScan(basePackages={\"com.ascendia.jobs\",\"com.ascendia.shared\"})", 'Move a service outside the scanned package, observe the failure, then fix the package boundary.', 'Component scanning finds annotated classes in selected packages and registers them as beans.'),
    $lesson('What is the bean lifecycle?', 'Spring instantiates a bean, injects dependencies, invokes initialization callbacks, serves it, and invokes destruction callbacks when the context closes.', "@PostConstruct void initialize() {}\n@PreDestroy void close() {}", 'Log each lifecycle phase and close the test context.', 'The container coordinates creation, dependency injection, initialization and destruction callbacks.'),
    $lesson('What is @PostConstruct?', '@PostConstruct marks a method to run after dependency injection. Keep it fast and fail clearly if required configuration is invalid.', "@PostConstruct\nvoid validateConfiguration() {\n Assert.hasText(apiUrl, \"apiUrl is required\");\n}", 'Validate one required property during bean initialization.', '@PostConstruct runs after dependencies are injected and before normal bean use.'),
    $lesson('What is @PreDestroy?', '@PreDestroy marks cleanup logic invoked when a managed singleton is being destroyed during an orderly context shutdown.', "@PreDestroy\nvoid shutdown() { executor.shutdown(); }", 'Create a managed executor and shut it down without accepting new tasks.', '@PreDestroy is used for cleanup before a managed bean is destroyed.'),

    $lesson('How do you create a REST API?', 'A REST API uses resource-oriented routes, DTOs, validation, a service layer, persistence and explicit HTTP responses.', "@RestController\n@RequestMapping(\"/api/v1/jobs\")\nclass JobController {\n @GetMapping Page<JobDto> index(Pageable pageable) { return service.index(pageable); }\n}", 'Build a paginated jobs endpoint without returning JPA entities directly.', 'A maintainable REST API separates transport DTOs, validation, business logic and persistence.'),
    $lesson('What are HTTP methods?', 'GET reads, POST creates, PUT replaces, PATCH partially updates and DELETE removes a resource.', "GET /api/jobs\nPOST /api/jobs\nPUT /api/jobs/42\nPATCH /api/jobs/42\nDELETE /api/jobs/42", 'Design CRUD routes for job applications and identify idempotent operations.', 'HTTP methods communicate the intended resource operation.'),
    $lesson('PUT versus PATCH', 'PUT represents a complete replacement and should be idempotent; PATCH applies a partial modification and needs an explicit patch contract.', "@PatchMapping(\"/{id}\")\nJobDto updateStatus(@PathVariable long id, @RequestBody UpdateStatusRequest request) { return service.updateStatus(id, request); }", 'Implement a PATCH that changes only application status.', 'PUT replaces the representation; PATCH modifies selected fields.'),
    $lesson('What is ResponseEntity?', 'ResponseEntity provides control over response status, headers and body.', "URI location = URI.create(\"/api/v1/jobs/\" + job.id());\nreturn ResponseEntity.created(location).body(job);", 'Return 201 Created with a Location header after creating a job.', 'ResponseEntity explicitly represents the HTTP status, headers and body.'),
    $lesson('Which HTTP status codes should APIs use?', 'Use status codes consistently: 200 success, 201 creation, 204 no body, 400 invalid request, 401 unauthenticated, 403 forbidden, 404 missing, 409 conflict and 500 unexpected failure.', "return ResponseEntity.noContent().build(); // successful DELETE", 'Map five job-portal outcomes to appropriate status codes.', 'Status codes should accurately describe the HTTP outcome rather than always returning 200.'),
    $lesson('How do you validate API requests?', 'Jakarta Bean Validation annotations define field constraints, while @Valid activates validation for a request DTO.', "record CreateUserRequest(@NotBlank String name, @Email String email) {}\n@PostMapping UserDto create(@Valid @RequestBody CreateUserRequest request) { return service.create(request); }", 'Test blank name and malformed email and inspect the 400 response.', '@Valid plus Bean Validation constraints validates a deserialized request DTO.'),
    $lesson('What is global exception handling?', '@RestControllerAdvice centralizes exception-to-response mapping so controllers remain focused and errors stay consistent.', "@RestControllerAdvice\nclass ApiErrors {\n @ExceptionHandler(JobNotFoundException.class)\n ResponseEntity<ApiError> missing(JobNotFoundException ex) { return ResponseEntity.status(404).body(ApiError.of(ex.getMessage())); }\n}", 'Handle validation, not-found and conflict errors in one advice class.', '@RestControllerAdvice applies centralized exception handling across REST controllers.'),
    $lesson('How do you create a custom exception?', 'A domain exception gives a meaningful name and context to a business failure and is mapped at the API boundary.', "class JobNotFoundException extends RuntimeException {\n JobNotFoundException(long id) { super(\"Job \" + id + \" was not found\"); }\n}", 'Throw the exception from a service when findById returns empty.', 'A custom exception represents a specific application failure and can be mapped centrally.'),
    $lesson('How should APIs return errors?', 'Return a stable JSON contract containing status, code, message, timestamp, path and optional field errors; never leak stack traces.', "record ApiError(Instant timestamp, int status, String code, String message, String path) {}", 'Create one response for a missing job and one for invalid fields.', 'Consistent structured error JSON makes clients reliable and avoids leaking internals.'),
    $lesson('What is API versioning?', 'Versioning protects clients when introducing breaking contracts. URI, header and media-type versioning are common strategies.', "@RequestMapping(\"/api/v1/jobs\")\nclass JobV1Controller {}", 'Introduce a v2 DTO without silently breaking v1 consumers.', 'API versioning allows incompatible contracts to coexist during migration.'),

    $lesson('What is JPA?', 'Jakarta Persistence is the Java specification for mapping object state and relationships to relational database structures.', "@Entity\nclass Job { @Id @GeneratedValue Long id; String title; }", 'Map a Job entity and persist it in an integration test.', 'JPA is a persistence specification; providers implement its ORM behavior.'),
    $lesson('What is Hibernate?', 'Hibernate is a widely used JPA implementation that supplies the persistence context, dirty checking, SQL generation and relationship loading.', "spring.jpa.show-sql=true\nspring.jpa.properties.hibernate.format_sql=true", 'Enable SQL logging locally and observe an entity insert.', 'Hibernate is an ORM implementation commonly used as the JPA provider.'),
    $lesson('What is an entity?', 'An entity is a persistent class with an identity. It needs an @Id and should protect invariants rather than acting as an unvalidated API payload.', "@Entity\n@Table(name=\"jobs\")\nclass Job {\n @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;\n @Column(nullable=false) private String title;\n}", 'Add a non-null title and a unique external job identifier.', 'An entity represents persistent domain state identified by an @Id.'),
    $lesson('What is JpaRepository?', 'JpaRepository supplies CRUD, paging, sorting, query derivation and custom-query integration for an entity and ID type.', "interface JobRepository extends JpaRepository<Job, Long> {\n Page<Job> findByStatus(String status, Pageable pageable);\n}", 'Create a paginated repository query for published jobs.', 'JpaRepository provides typed persistence operations plus paging and sorting.'),
    $lesson('save() versus saveAndFlush()', 'save schedules persistence through the persistence context; saveAndFlush also requests an immediate synchronization with the database.', "Job saved = repository.save(job);\nrepository.flush(); // only when immediate DB synchronization is required", 'Demonstrate normal transaction commit and explain when an early flush is necessary.', 'saveAndFlush requests an immediate flush, while save normally relies on transaction flush timing.'),
    $lesson('What is lazy loading?', 'Lazy relationships are loaded when accessed. They reduce unnecessary data but require an active context or an explicit fetch plan.', "@OneToMany(mappedBy=\"company\", fetch=FetchType.LAZY)\nprivate List<Job> jobs = new ArrayList<>();", 'Serialize a DTO inside a transaction without exposing a lazy entity graph.', 'Lazy loading defers retrieval of related data until it is accessed.'),
    $lesson('What is eager loading?', 'Eager relationships are requested with the owning entity and can over-fetch data. Prefer query-specific fetch plans over making every relationship eager.', "@EntityGraph(attributePaths=\"company\")\nPage<Job> findByStatus(String status, Pageable pageable);", 'Compare SQL for eager mapping and an EntityGraph query.', 'Eager loading retrieves a relationship as part of the entity load plan.'),
    $lesson('What is the N+1 query problem?', 'N+1 occurs when one query loads a list and additional queries load a relationship for each row, causing latency and database load.', "@Query(\"select j from Job j join fetch j.company where j.status = :status\")\nList<Job> findPublishedWithCompany(String status);", 'Measure query count for 100 jobs before and after a fetch join.', 'N+1 means one list query plus repeated per-row relationship queries.'),
    $lesson('What is cascade?', 'Cascade propagates selected persistence operations from a parent entity to related entities. REMOVE and ALL must be used carefully.', "@OneToMany(mappedBy=\"job\", cascade={CascadeType.PERSIST, CascadeType.MERGE}, orphanRemoval=true)\nprivate List<JobSkill> skills;", 'Persist a job and its new skills in one transaction without cascading deletion to shared records.', 'Cascade controls which entity operations propagate to associated entities.'),
    $lesson('What is @Transactional?', '@Transactional defines a transaction boundary. Successful completion commits; matching unchecked failures roll back by default.', "@Transactional\npublic void transfer(long from, long to, BigDecimal amount) {\n debit(from, amount);\n credit(to, amount);\n}", 'Write an integration test proving both updates roll back when credit fails.', '@Transactional executes the method within a transaction and supports atomic rollback rules.'),
];
